import { build } from 'esbuild'
import { rmSync, writeFileSync } from 'node:fs'

/**
 * Bundle the Express app into plain JS for Vercel's Node runtime.
 * @vercel/node only reliably compiles the api entry; relative .ts imports
 * otherwise survive into /var/task and crash Node with ERR_MODULE_NOT_FOUND.
 */
await build({
  entryPoints: ['app.ts'],
  bundle: true,
  platform: 'node',
  format: 'esm',
  outfile: 'api/app.bundle.mjs',
  packages: 'external',
  legalComments: 'none',
  logLevel: 'info',
})

writeFileSync(
  'api/index.js',
  [
    '// Generated by scripts/build-vercel-api.mjs — do not edit by hand.',
    "import app from './app.bundle.mjs'",
    'export default app',
    '',
  ].join('\n'),
)

// Prefer the generated JS entry over the TypeScript stub during deploy.
try {
  rmSync('api/index.ts')
} catch {
  // stub may already be absent in some environments
}

console.log('Built Vercel API entry: api/index.js + api/app.bundle.mjs')
